def is_palindrome(s):
    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]

def title_case_words(s):
    words = s.split()
    return " ".join(w[0].upper() + w[1:].lower() if w else w for w in words)

def char_frequency(s):
    d = {}
    for c in s.lower():
        if c.isalpha():
            d[c] = d.get(c, 0) + 1
    return d

def is_anagram(a, b):
    norm = lambda s: sorted(c for c in s.lower() if c != " ")
    return norm(a) == norm(b)

def longest_word(s):
    words = s.split()
    if not words:
        return ""
    longest = words[0]
    for w in words[1:]:
        if len(w) > len(longest):
            longest = w
    return longest

def is_pangram(s):
    letters = set(c.lower() for c in s if c.isalpha())
    return set("abcdefghijklmnopqrstuvwxyz") <= letters

def first_non_repeating_char(s):
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    for c in s:
        if counts[c] == 1:
            return c
    return ""

def run_length_encode(s):
    if not s:
        return ""
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1
    result.append(prev + str(count))
    return "".join(result)

def count_substring_occurrences(s, sub):
    if sub == "":
        return 0
    count = 0
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        count += 1
        start = idx + len(sub)
    return count

def most_common_char(s):
    if not s:
        return ""
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    best = s[0]
    best_count = counts[s[0]]
    for c in s:
        if counts[c] > best_count:
            best = c
            best_count = counts[c]
    return best
